```cpp
#include <iostream>
#include <string>
#include <regex>

// Fonction de conversion Markdown vers HTML
std::string markdown_to_html(const std::string& markdown) {
    std::string html;

    // Conversion des balises Markdown en HTML
    std::regex header_regex("^#+( *)\\s*(.+)$");  // Têtes de niveau 1 à 6
    std::regex strong_regex("\\*([^*]+)\\*");    // Gras
    std::regex italic_regex("_(.+)_");         // Italique
    std::regex link_regex("\\[([^\\]]+)\\]\\(([^)]+)\\)");  // Liens
    std::regex code_block_regex("```(.*?)```");    // Blocs de code

    // Remplacement des balises Markdown par leurs équivalents HTML
    std::replace_if(markdown.begin(), markdown.end(), [](char c) {
        return c == '#';  // Remplacer les têtes de niveau 1 par leur équivalent HTML
    }, [&html](char c) {
        html += "<h" + std::to_string(c - '#') + ">";
        return c;
    });
    std::replace_if(markdown.begin(), markdown.end(), std::regex(strong_regex), [](std::cmatch& match) {
        html += "<strong>" + match[1] + "</strong>";
        return match.end();
    });
    std::replace_if(markdown.begin(), markdown.end(), std::regex(italic_regex), [](std::cmatch& match) {
        html += "<em>" + match[1] + "</em>";
        return match.end();
    });
    std::replace_if(markdown.begin(), markdown.end(), std::regex(link_regex), [](std::cmatch& match) {
        html += "<a href=\"" + match[2] + "\">" + match[1] + "</a>";
        return match.end();
    });
    std::replace_if(markdown.begin(), markdown.end(), std::regex(code_block_regex), [](std::cmatch& match) {
        html += "<pre><code>" + match[1] + "</code></pre>";
        return match.end();
    });

    // Ajouter la balise de fin de document HTML
    html += "</body></html>";

    return html;
}

int main() {
    std::string markdown = "## Titre de niveau 2\n"
                           "*Ceci est en gras*\n"
                           "_Ceci est en italique_\n"
                           "[Liens](http://example.com)\n"
                           "```C++\n"
                           "int main() {\n"
                           "    return 0;\n"
                           "}\n"
                           "```";

    std::string html = markdown_to_html(markdown);

    std::cout << "Markdown:\n" << markdown << "\n";
    std::cout << "HTML:\n" << html << "\n";

    return 0;
}
```

Cette fonction utilise la bibliothèque de régularité de C++ (std::regex) pour trouver et remplacer les balises Markdown par leurs équivalents HTML. La fonction prend en entrée une chaîne de caractères contenant du texte au format Markdown, et renvoie une chaîne de caractères contenant du texte au format HTML. L'exemple de fonction ci-dessus convertit le texte Markdown fourni dans le corps de la fonction, mais vous pouvez également l'appeler avec une référence à une chaîne de caractères existante.

